from pathlib import Path
import json,hashlib,base64,zlib,tempfile,sys,importlib.util
import numpy as np
p=Path(__file__).resolve().parent
bench=Path('experiments/gpu-physics/benchmarks');file=bench/'2026-09-29-rain-reduced-structured-reference.json';receipt=json.loads(file.read_text());parentfile=Path(receipt['parent_reference']['receipt']);assert hashlib.sha256(parentfile.read_bytes()).hexdigest()==receipt['parent_reference']['sha256'];parent=json.loads(parentfile.read_text());raw=zlib.decompress(base64.b64decode(parent['input_trace']['data']));assert hashlib.sha256(raw).hexdigest()==parent['input_trace']['sha256']
with tempfile.TemporaryDirectory(prefix='rain-reduced-portable-') as tmp:
 base=Path(tmp);trace=base/parent['input_trace']['relative_path'];trace.parent.mkdir(parents=True);trace.write_bytes(raw);directory=base/'rain-coupled-reference';directory.mkdir()
 for name in ['model.py','wave.py']:(directory/name).write_text(parent['sources'][name])
 sys.path.insert(0,str(directory));import model as m;from wave import wave
 def check(x):
  natural=float(np.max(abs(m.residual(x))/(1+abs(x))));_,sweep=wave(x);grad=m.gradient_primal(x);dense=m.H@x+m.g;agreement=float(np.max(abs(grad-dense)/(1+np.maximum(abs(grad),abs(dense)))));feas=[]
  for b in m.blocks:
   val=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
   if domain=='positive':error=max(0,-float(min(val)))
   elif domain=='box':error=max(0,float(max(abs(val)))-cap)/(1+cap)
   elif domain=='ball':error=max(0,float(np.linalg.norm(val))-cap)/(1+cap)
   feas.append(error)
  return dict(natural=natural,feasibility=max(feas),primal_agreement=agreement,sweep=sweep,passed=bool(natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5))
 out={};velocities=[]
 for name in ['cold','capped']:
  state=receipt['states'][name+'/solution.npz'];x=np.array(state['impulses']);metrics=check(x);assert metrics['passed'];velocity=m.vfree+m.M@m.J.T@x;delta=float(np.max(abs(velocity-np.array(state['velocities']))));assert delta<1e-12;velocities.append(velocity)
  bad=x.copy();bad[0]+=.01;bad_result=check(bad);assert not bad_result['passed']
  out[name]=dict(verification=metrics,stored_velocity_difference=delta,corruption_rejected=True,float32_cache_storage_only=check(x.astype(np.float32).astype(np.float64)))
 result=dict(status='portable-reference-verification-pass',arms=out,cold_capped_velocity_max_difference=float(np.max(abs(velocities[0]-velocities[1]))),scope='Reconstructed exclusively from portable receipts in a temporary directory. Quantized cache check uses float64 arithmetic and is NOT float32 solver or GPU qualification.')
(p/'portable-validation.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))

